        var unavailable=l.getRecipeManager().getAllRecipesFor(AspRecipes.MOLECULAR.get()).stream().filter(r->r.value().outputTag().equals("c:gems/ruby")).findFirst().orElseThrow().value();check("optional addon output tag cannot consume input when absent",!unavailable.matches(new SingleRecipeInput(new ItemStack(Items.REDSTONE)),l),"ruby absent");var counted=new MolecularRecipe(Ingredient.of(Items.IRON_INGOT),2,new ItemStack(Items.GOLD_INGOT),"",10);check("molecular ingredient count enforced",!counted.matches(new SingleRecipeInput(new ItemStack(Items.IRON_INGOT)),l)&&counted.matches(new SingleRecipeInput(new ItemStack(Items.IRON_INGOT,2)),l),"count2");
        var actor=FakePlayerFactory.getMinecraft(l);actor.getInventory().clearContent();actor.setPos(base.getX(),base.getY()+3,base.getZ());for(var item:new ItemArmourSolarHelmet[]{AspItems.ADVANCED_SOLAR_HELMET.get(),AspItems.HYBRID_SOLAR_HELMET.get(),AspItems.ULTIMATE_SOLAR_HELMET.get()}){var helmet=new ItemStack(item);actor.setItemSlot(EquipmentSlot.HEAD,helmet);item.onArmorTick(l,actor,helmet);check("solar helmet "+item.type+" self-generates EU",ElectricItem.manager.getCharge(helmet)==item.config().day().get(),ElectricItem.manager.getCharge(helmet));}
        var h=AspItems.HYBRID_SOLAR_HELMET.get();var hs=h.charged();actor.setItemSlot(EquipmentSlot.HEAD,hs);actor.setAirSupply(80);before=ElectricItem.manager.getCharge(hs);h.onArmorTick(l,actor,hs);check("hybrid solar helmet replenishes air for 1000 EU",actor.getAirSupply()==280&&ElectricItem.manager.getCharge(hs)==before-1000+64,actor.getAirSupply());actor.setItemSlot(EquipmentSlot.CHEST,new ItemStack(Ic2Items.ELECTRIC_JETPACK.get()));before=ElectricItem.manager.getCharge(hs);h.onArmorTick(l,actor,hs);check("solar helmet prioritizes armour before itself",ElectricItem.manager.getCharge(actor.getItemBySlot(EquipmentSlot.CHEST))==60&&ElectricItem.manager.getCharge(hs)==before+4,ElectricItem.manager.getCharge(hs));var chest=actor.getItemBySlot(EquipmentSlot.CHEST);ElectricItem.manager.charge(chest,((ic2.api.item.IElectricItem)chest.getItem()).getMaxCharge(chest)-ElectricItem.manager.getCharge(chest)-.5,3,true,false);before=ElectricItem.manager.getCharge(hs);h.onArmorTick(l,actor,hs);check("helmet preserves fractional EU when finishing armour charge",ElectricItem.manager.getCharge(chest)==((ic2.api.item.IElectricItem)chest.getItem()).getMaxCharge(chest)&&ElectricItem.manager.getCharge(hs)==before+63.5,ElectricItem.manager.getCharge(hs)-before);boolean armourOnly=AspConfig.HELMET_ARMOUR_ONLY.get();try{AspConfig.HELMET_ARMOUR_ONLY.set(false);actor.setItemSlot(EquipmentSlot.CHEST,ItemStack.EMPTY);actor.getInventory().setItem(0,new ItemStack(Ic2Items.RE_BATTERY.get()));h.onArmorTick(l,actor,hs);check("helmet whole inventory config charges hotbar",ElectricItem.manager.getCharge(actor.getInventory().getItem(0))==64,ElectricItem.manager.getCharge(actor.getInventory().getItem(0)));}finally{AspConfig.HELMET_ARMOUR_ONLY.set(armourOnly);}check("hybrid and ultimate dye tags exclude advanced",hs.is(net.minecraft.tags.ItemTags.DYEABLE)&&!new ItemStack(AspItems.ADVANCED_SOLAR_HELMET.get()).is(net.minecraft.tags.ItemTags.DYEABLE),"dyeable tag");actor.getInventory().clearContent();
