        var upgrade=CraftingInput.of(2,1,List.of(hybrid,new ItemStack(AspBlocks.ULTIMATE_SOLAR_PANEL.get())));var upgraded=l.getRecipeManager().getRecipeFor(RecipeType.CRAFTING,upgrade,l).map(r->r.value().assemble(upgrade,l.registryAccess())).orElse(ItemStack.EMPTY);check("ultimate solar helmet upgrade retains charge and colour",upgraded.is(AspItems.ULTIMATE_SOLAR_HELMET.get())&&ElectricItem.manager.getCharge(upgraded)==12345&&upgraded.get(DataComponents.DYED_COLOR)!=null&&upgraded.get(DataComponents.DYED_COLOR).rgb()==0x35aaff,upgraded);
        var dye=CraftingInput.of(2,1,List.of(new ItemStack(AspItems.HYBRID_SOLAR_HELMET.get()),new ItemStack(Items.BLUE_DYE)));var dyed=l.getRecipeManager().getRecipeFor(RecipeType.CRAFTING,dye,l).map(r->r.value().assemble(dye,l.registryAccess())).orElse(ItemStack.EMPTY);check("modern vanilla dye recipe colours solar helmet",dyed.is(AspItems.HYBRID_SOLAR_HELMET.get())&&dyed.has(DataComponents.DYED_COLOR),dyed);
        boolean recipes=true;for(var item:AspItems.REGISTRY.getEntries()){String id=item.getId().getPath();if(Set.of("quantum_generator","iridium_ingot","uranium_ingot","sunnarium_part").contains(id))continue;recipes&=l.getRecipeManager().getRecipes().stream().anyMatch(r->r.value().getResultItem(l.registryAccess()).is(item.get()));}check("all survival crafting and molecular outputs have recipes",recipes,"registered items");check("IC2 compressor accepts deepslate uranium for ASP",ic2.api.recipe.Recipes.compressor.getOutputFor(new ItemStack(Ic2Blocks.DEEPSLATE_URANIUM_ORE.get()),false)!=null,"API recipe");
